#include <bits/stdc++.h>
using namespace std;

// ---- double-double arithmetic (~106-bit mantissa) for the near-boundary slow path ----
struct dd { double hi, lo; };
static dd twoSum(double a, double b) { double s = a + b, bb = s - a; return {s, (a - (s - bb)) + (b - bb)}; }
static dd quickTwoSum(double a, double b) { double s = a + b; return {s, b - (s - a)}; }
static dd twoProd(double a, double b) { double p = a * b; return {p, fma(a, b, -p)}; }
static dd add(dd a, dd b) {
    dd s = twoSum(a.hi, b.hi), t = twoSum(a.lo, b.lo);
    s.lo += t.hi;
    s = quickTwoSum(s.hi, s.lo);
    s.lo += t.lo;
    return quickTwoSum(s.hi, s.lo);
}
static dd neg(dd a) { return {-a.hi, -a.lo}; }
static dd sub(dd a, dd b) { return add(a, neg(b)); }
static dd mul(dd a, dd b) { dd p = twoProd(a.hi, b.hi); p.lo += a.hi * b.lo + a.lo * b.hi; return quickTwoSum(p.hi, p.lo); }
static dd divd(dd a, dd b) {
    double q1 = a.hi / b.hi;
    dd r = sub(a, mul(b, {q1, 0}));
    double q2 = r.hi / b.hi;
    r = sub(r, mul(b, {q2, 0}));
    double q3 = r.hi / b.hi;
    return add(quickTwoSum(q1, q2), {q3, 0});
}
static dd sqrtd(dd a) {
    if (a.hi <= 0) return {0, 0};
    double s = sqrt(a.hi);
    dd e = sub(a, twoProd(s, s));
    return quickTwoSum(s, e.hi / (2 * s));
}
static dd D(double x) { return {x, 0}; }
static bool tiny(dd term, dd total) { return fabs(term.hi) <= 1e-34 * fabs(total.hi); }
static const dd PI = {3.141592653589793116e+00, 1.224646799147353207e-16};

static dd ddSin(dd x) {
    dd term = x, total = x, x2 = mul(x, x);
    for (int i = 1; i < 200; i++) {
        term = mul(term, neg(divd(x2, D((2.0 * i) * (2 * i + 1)))));
        if (tiny(term, total)) break;
        total = add(total, term);
    }
    return total;
}
static dd ddCos(dd x) {
    dd term = D(1), total = D(1), x2 = mul(x, x);
    for (int i = 1; i < 200; i++) {
        term = mul(term, neg(divd(x2, D((2.0 * i - 1) * (2 * i)))));
        if (tiny(term, total)) break;
        total = add(total, term);
    }
    return total;
}
static dd ddAtan(dd x) {
    if (x.hi < 0) return neg(ddAtan(neg(x)));
    int scale = 0;
    // Halve the angle until the Taylor series converges quickly.
    while (x.hi > 0.05) { x = divd(x, add(D(1), sqrtd(add(D(1), mul(x, x))))); scale++; }
    dd term = x, total = x, x2 = mul(x, x);
    for (int i = 1; i < 200; i++) {
        term = mul(term, neg(x2));
        dd piece = divd(term, D(2 * i + 1));
        if (tiny(piece, total)) break;
        total = add(total, piece);
    }
    return mul(total, D(ldexp(1.0, scale)));
}
static dd ddAtan2(dd y, dd x) {
    if (x.hi == 0) return divd(PI, D(2));
    if (y.hi == 0) return D(0);
    return x.hi > 0 ? ddAtan(divd(y, x)) : sub(PI, ddAtan(divd(y, neg(x))));
}
// Exact-enough parse of a plain decimal string such as -12.345678901234567890.
static dd parseDD(const string &s) {
    size_t p = 0;
    bool negative = false;
    if (p < s.size() && (s[p] == '-' || s[p] == '+')) negative = s[p++] == '-';
    long long ip = 0, frac = 0, scale = 1;
    while (p < s.size() && isdigit((unsigned char)s[p])) ip = ip * 10 + (s[p++] - '0');
    if (p < s.size() && s[p] == '.') p++;
    for (int k = 0; p < s.size() && isdigit((unsigned char)s[p]) && k < 18; k++) { frac = frac * 10 + (s[p++] - '0'); scale *= 10; }
    auto fromInt = [](long long v) { double h = (double)v; return dd{h, (double)(v - (long long)h)}; };
    dd v = add(fromInt(ip), divd(fromInt(frac), fromInt(scale)));
    return negative ? neg(v) : v;
}

static long long slowRoundKm(const string &s1, const string &s2, const string &s3, const string &s4) {
    dd lat1 = parseDD(s1), lon1 = parseDD(s2), lat2 = parseDD(s3), lon2 = parseDD(s4);
    dd k = divd(PI, D(180));
    dd p1 = mul(lat1, k), p2 = mul(lat2, k), dp = mul(sub(lat2, lat1), k), dl = mul(sub(lon2, lon1), k);
    dd sp = ddSin(divd(dp, D(2))), sl = ddSin(divd(dl, D(2)));
    dd a = add(mul(sp, sp), mul(mul(ddCos(p1), ddCos(p2)), mul(sl, sl)));
    if (a.hi < 0) a = D(0);
    if (a.hi > 1 || (a.hi == 1 && a.lo > 0)) a = D(1);
    dd km = mul(D(6371 * 2), ddAtan2(sqrtd(a), sqrtd(sub(D(1), a))));
    dd t = add(km, D(0.5));
    double f = floor(t.hi);
    if (f == t.hi) f += floor(t.lo);
    return (long long)f;
}

static long long halfUpKm(const string &s1, const string &s2, const string &s3, const string &s4) {
    const double degToRad = M_PI / 180.0;
    double lat1 = strtod(s1.c_str(), nullptr), lon1 = strtod(s2.c_str(), nullptr);
    double lat2 = strtod(s3.c_str(), nullptr), lon2 = strtod(s4.c_str(), nullptr);
    double p1 = lat1 * degToRad, p2 = lat2 * degToRad;
    double dp = (lat2 - lat1) * degToRad, dl = (lon2 - lon1) * degToRad;
    double sp = sin(dp / 2), sl = sin(dl / 2);
    double a = sp * sp + cos(p1) * cos(p2) * (sl * sl);
    a = min(1.0, max(0.0, a));
    double km = 6371.0 * (2 * atan2(sqrt(a), sqrt(1.0 - a)));
    // Doubles can cross a half-kilometre boundary: recompute those (and near-antipodal) cases precisely.
    if (fabs(km - (floor(km) + 0.5)) < 1e-5 || km > 20015.0) return slowRoundKm(s1, s2, s3, s4);
    return (long long)floor(km + 0.5);
}

